<script setup>
import { Link, router } from '@inertiajs/vue3';import {ref} from 'vue';import AppLayout from '../../Layouts/AppLayout.vue';
const props=defineProps({products:Object,filters:Object});const q=ref(props.filters?.q||'');const money=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n);
const search=()=>router.get('/',{q:q.value},{preserveState:true});
</script>
<template><AppLayout><section class="hero"><div><div style="font-weight:700;color:#bcd0ff">SELAMAT DATANG DI TOKOKITA</div><h1>Temukan produk favoritmu, mulai dari sini.</h1><p>Belanja kebutuhan pilihan dengan pengalaman yang simpel, nyaman, dan praktis.</p><a href="#produk" class="btn" style="background:white;color:#2457d6">Mulai Belanja →</a></div><div class="hero-art">🛍️</div></section><div class="section-head"><div><h2 id="produk">Produk Pilihan</h2><div class="muted">Pilihan terbaik untuk kamu</div></div><form @submit.prevent="search" class="row"><input v-model="q" placeholder="Cari produk..." style="padding:11px;border:1px solid #dce2ed;border-radius:10px"><button class="btn">Cari</button></form></div><div class="grid"><article v-for="p in products.data" :key="p.id" class="product"><Link :href="`/produk/${p.id}`"><div class="product-img">{{p.image||'📦'}}</div><div class="product-body"><div class="muted" style="font-size:12px">{{p.category?.name||'Umum'}}</div><strong>{{p.name}}</strong><div class="price">{{money(p.price)}}</div><div class="muted">Stok: {{p.stock}}</div></div></Link></article></div><div v-if="!products.data.length" class="panel" style="text-align:center;margin-top:20px">Produk tidak ditemukan.</div><div class="row" style="justify-content:center;margin:28px"><Link v-if="products.prev_page_url" :href="products.prev_page_url" class="btn light">Sebelumnya</Link><span class="muted">Halaman {{products.current_page}} dari {{products.last_page}}</span><Link v-if="products.next_page_url" :href="products.next_page_url" class="btn light">Berikutnya</Link></div></AppLayout></template>
